    table[static_cast<int>(LK::Ignores_the_value)] = "Ignores the value sent by the game\nand uses the value set below";
    table[static_cast<int>(LK::Enable_OptiScaler_s)] = "Enable OptiScaler's sharpening filter\nBy default uses a sharpening value provided by the game\nSelect 'Override' under 'Sharpness' and adjust the slider\nto change it\n\nSome upscalers have their own sharpness filter, so this\noption is not always needed";
    table[static_cast<int>(LK::Use_AMD_s)] = "Use AMD's RCAS\nModified to add Contrast parameter\nand MAS support";
    table[static_cast<int>(LK::Use_Depth_Aware)] = "Use Depth Aware Sharpening (RCAS)\nSmarter sharpening with less artifacts,\nbut also heavier\n\nThe farther away is the object, the more\nsharpening is applied";
    table[static_cast<int>(LK::Use_Depth_Aware_2)] = "Use Depth Aware Sharpening (DAS)\nDepth-aware directional adaptive luma sharpener\nSmarter sharpening with less artifacts,\nbut also heavier\n\nThe farther away is the object, the more\nsharpening is applied";
    table[static_cast<int>(LK::Enable_DA_MAS)] = "Enable DA + MAS debug views\nBlue tint for DA detected edges\n\nMore red areas will have more sharpness applied\nGreen areas will get reduced sharpness";
    table[static_cast<int>(LK::Clamps_the_final)] = "Clamps the final image to the [0, 1] range.\n\nPrevents overshoot artifacts such as bright halos or negative colors.\nRecommended for LDR pipelines; optional for HDR depending on tone-mapping.\n\nWhen not set OptiScaler controls it via upscalers HDR flag";
    table[static_cast<int>(LK::Ignores_small_depth)] = "Ignores small depth differences before edge detection.\n\nHigher values reduce flickering and noise from minor depth changes, but may soften real geometry edges.\nLower values preserve fine detail but can cause unstable or noisy edge detection.";
    table[static_cast<int>(LK::Controls_how_strongly)] = "Controls how strongly sharpening is reduced across depth edges.\n\nHigher values more aggressively prevent sharpening across object boundaries (reduces halos).\nLower values allow more sharpening to pass across edges (sharper but riskier).";
    table[static_cast<int>(LK::Ignores_small_depth_2)] = "Ignores small depth differences before edge detection.\n\nHigher values reduce flickering and noise from minor depth changes, but may soften real geometry edges.\nLower values preserve fine detail but can cause unstable or noisy edge detection.";
    table[static_cast<int>(LK::Controls_how_strongly_2)] = "Controls how strongly sharpening is reduced across depth edges.\n\nHigher values more aggressively prevent sharpening across object boundaries (reduces halos).\nLower values allow more sharpening to pass across edges (sharper but riskier).";
    table[static_cast<int>(LK::Positive_values_decrease)] = "Positive values decrease sharpness at high contrast areas.\nNegative values increase sharpness at high contrast areas.";
    table[static_cast<int>(LK::Areas_that_are)] = "Areas that are more red will have more sharpness applied\nGreen areas will get reduced sharpness";
    table[static_cast<int>(LK::Maximum_amount_of)] = "Maximum amount of sharpness that motion can add or remove.\n\nNegative values reduce sharpening in motion (recommended).\nPositive values increase sharpening in motion.\n\nThe final adjustment scales with motion and is capped at this value.";
    table[static_cast<int>(LK::Minimum_motion_required)] = "Minimum motion required before motion-based sharpening adjustment begins.\n\nHigher values ignore small movements (more stable).\nLower values react to subtle motion (more sensitive).";
    table[static_cast<int>(LK::Defines_the_motion)] = "Defines the motion range over which the effect ramps from zero to full strength.\n\nValues above the threshold are mapped into this range.\nLarger values make the response smoother and more gradual.\nSmaller values make the effect react more quickly and aggressively.";
    table[static_cast<int>(LK::Overrides_every_upscaler)] = "Overrides every upscaler preset with the set value\n\n1.5x on a 1080p screen means an internal res of 720p\n1080 / 1.5 = 720";
    table[static_cast<int>(LK::Lets_you_override)] = "Lets you override each preset's ratio individually\nNote that not every game supports every quality preset\n\n1.5x on a 1080p screen means internal resolution of 720p\n1080 / 1.5 = 720";
    table[static_cast<int>(LK::Upscales_the_image)] = "Upscales the image internally to a higher output resolution\nthen downscales it back to your display resolution\n\nValues <1.0 make the upscaler cheaper\nValues >1.0 make image sharper at the cost of performance\n\nIf greyed out, please check Git Wiki - Unreal Engine tweaks\n\nTarget res and total ratio at the bottom (max. total 3.0!)";
    table[static_cast<int>(LK::Some_Unreal_Engine)] = "Some Unreal Engine games need this\n\nTry using if colours flickering or\nobjects have ghosting trails";
    table[static_cast<int>(LK::Allows_the_use)] = "Allows the use of a Reactive mask\nKeep in mind that a Reactive mask sent to DLSS\nwill not produce a good image in combination with FSR/XeSS";
    table[static_cast<int>(LK::Mostly_a_fix)] = "Mostly a fix for Unreal Engine games\nTop left part of the screen will be blurry";
    table[static_cast<int>(LK::Extended_sliders_limit)] = "Extended sliders limit for quality presets\n\nUsing this option changes resolution detection logic\nand might cause issues and crashes!";
    table[static_cast<int>(LK::This_setting_will)] = "This setting will become active on next boot!";
    table[static_cast<int>(LK::This_setting_will_2)] = "This setting will become active on next boot!";
    table[static_cast<int>(LK::Controls_the_DXGI)] = "Controls the DXGI Present sync interval, which determines how\nthe swap chain waits for vertical refresh.\n\n0  = Present immediately, no VSync wait.\n1  = Sync to every refresh, normal VSync.\n2+ = Present every N refreshes, reducing effective frame rate.\n\nHigher values can reduce tearing but may increase latency and cap FPS.\nFor most games, use 0 for lowest latency or 1 for normal VSync.";
    table[static_cast<int>(LK::Can_help_with)] = "Can help with blurry textures in broken games\nNegative values will make textures sharper\nPositive values will make textures more blurry\n\nHas a small performance impact";
    table[static_cast<int>(LK::Apply_override_value)] = "Apply override value as scale multiplier\nWhen using scale mode, please use positive\noverride values to increase sharpness!";
